-- Table: syllabus_taxonomy (192 records)
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.polity.constitution_features', 'General Studies', 'polity', 'Constitutional Framework, Historical Underpinnings & Basic Structure', 'Preamble, Fundamental Rights, Directive Principles of State Policy, Fundamental Duties, Amendments, and Basic Structure Doctrine.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.polity.union_state_executive', 'General Studies', 'polity', 'Union and State Executives & Cabinets', 'President, Governor, Prime Minister, Council of Ministers, Ordinance Making, Pardoning Power, and Cabinet Committees.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.polity.parliament_legislatures', 'General Studies', 'polity', 'Parliament & State Legislatures', 'Lok Sabha, Rajya Sabha, State Assemblies, Money Bills, Legislative Procedures, and Parliamentary Privileges.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.polity.judiciary_system', 'General Studies', 'polity', 'Indian Judicial Architecture & Legal Safeguards', 'Supreme Court, High Courts, Collegium System, Judicial Activism, PIL, and Constitutional Writs under Articles 32 and 226.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.polity.federal_relations', 'General Studies', 'polity', 'Federalism, Center-State Relations & Emergency Provisions', 'Seventh Schedule legislative distribution, Inter-State Councils, and Emergency provisions under Articles 352, 356, and 360.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.polity.local_governance', 'General Studies', 'polity', 'Local Self-Government, Panchayati Raj & Municipalities', '73rd and 74th Constitutional Amendments, Eleventh and Twelfth Schedules, Gram Sabha, PRIs, ULBs, and PESA Act 1996.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.polity.statutory_bodies', 'General Studies', 'polity', 'Constitutional, Statutory, Regulatory & Quasi-Judicial Bodies', 'ECI, CAG, UPSC, Finance Commission, NHRC, NITI Aayog, Central Information Commission, and CVC.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.history.british_expansion', 'General Studies', 'history', 'British Colonial Expansion & Administrative Framework (1757–1857)', 'Plassey, Buxar, Subsidiary Alliance, Doctrine of Lapse, Permanent Settlement, Ryotwari, and colonial economic drain.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.history.revolt_1857_uprisings', 'General Studies', 'history', 'The 1857 Revolt & Early Resistance Movements', '1857 Revolt causes, leadership, Government of India Act 1858, Santhal Rebellion, Munda Uprising, and peasant revolts.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.history.socio_religious_reforms', 'General Studies', 'history', 'Socio-Religious Reform Movements & Renaissance', 'Brahmo Samaj, Arya Samaj, Ramakrishna Mission, Satyashodhak Samaj, Aligarh Movement, and anti-caste struggles.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.history.national_movement_early', 'General Studies', 'history', 'Early Nationalism, Moderate-Extremist Era & Swadeshi Movement', 'INC formation (1885), Moderate constitutionalism, Extremist resurgence, Bengal Partition (1905), and Swadeshi Movement.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.history.gandhian_era_mass_struggle', 'General Studies', 'history', 'Gandhian Era, Mass Struggles & Road to Independence', 'Non-Cooperation Movement, Civil Disobedience, Dandi March, Quit India Movement 1942, Subhas Chandra Bose, INA, and 1947 Partition.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.history.post_independence_consolidation', 'General Studies', 'history', 'Post-Independence Consolidation & Nation Building', 'Integration of Princely States, States Reorganisation Act 1956, tribal policies, linguistic states, and initial Five Year Plans.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ancient_medieval.indus_vedic', 'General Studies', 'ancient_medieval', 'Indus Valley Civilization & Vedic Period', 'Harappan urban architecture, trade links, Rig Vedic and Later Vedic society, religion, and iron age developments.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ancient_medieval.mauryan_gupta', 'General Studies', 'ancient_medieval', 'Rise of Heterodox Sects, Mauryan & Gupta Empires', 'Buddhism, Jainism, Mahajanapadas, Ashoka''s Dhamma, Arthashastra, and Gupta golden age in art and sciences.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ancient_medieval.delhi_sultanate_mughal', 'General Studies', 'ancient_medieval', 'Delhi Sultanate, Mughal Empire & Bhakti-Sufi Movements', 'Sultanate administration, Mughal Mansabdari system, Akbar''s policies, Maratha rise under Shivaji, and Bhakti/Sufi movements.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ancient_medieval.south_indian_dynasties', 'General Studies', 'ancient_medieval', 'South Indian Dynasties, Maritime Trade & Vijayanagara', 'Sangam Age literature, Chola local self-governance and naval expeditions, Pallavas, and Vijayanagara Empire.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.art_culture.architecture_sculpture', 'General Studies', 'art_culture', 'Indian Architecture, Sculptural Styles & Rock-Cut Traditions', 'Nagara, Dravida, and Vesara temple styles, Buddhist stupas, rock-cut caves (Ajanta, Ellora), and Indo-Islamic monuments.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.art_culture.performing_visual_arts', 'General Studies', 'art_culture', 'Performing Arts, Classical Music & Traditional Paintings', 'Eight classical dances, Hindustani and Carnatic classical music, and traditional Indian paintings (Mughal, Madhubani, Warli).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.art_culture.literature_philosophy', 'General Studies', 'art_culture', 'Classical Literature, Philosophical Schools & UNESCO Cultural Heritage', 'Shad-Darshana philosophical schools, classical Indian languages, Sanskrit epics, and UNESCO tangible/intangible heritage.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.geography_physical.geomorphology', 'General Studies', 'geography_physical', 'Geomorphology, Earth''s Interior & Landform Evolution', 'Earth interior, plate tectonics, continental drift, earthquakes, volcanoes, weathering, and fluvial/glacial/aeolian landforms.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.geography_physical.climatology_ocean', 'General Studies', 'geography_physical', 'Climatology, Atmospheric Circulation & Oceanography', 'Atmospheric structure, heat budget, planetary winds, cyclones, ocean currents, salinity, tides, and El Nino/La Nina/IOD.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.geography_india_world.physiography_drainage', 'General Studies', 'geography_india_world', 'Physiography of India & Drainage Systems', 'Himalayas, Indo-Gangetic plains, Peninsular plateau, coastal plains, and Himalayan and Peninsular river basins.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.geography_india_world.climate_soils_veg', 'General Studies', 'geography_india_world', 'Indian Monsoon, Soils & Natural Vegetation', 'South-West monsoon mechanism, western disturbances, major soil groups of India, and forest vegetation classifications.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.geography_india_world.resources_agriculture', 'General Studies', 'geography_india_world', 'Natural Resources, Mineral Wealth & Agricultural Patterns', 'Distribution of metallic/non-metallic minerals, coal, petroleum, renewable energy, and major cropping patterns.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.geography_india_world.population_economic', 'General Studies', 'geography_india_world', 'Human Geography, Demographics & Economic Geography', 'Demographic trends, Census data, urbanization, industrial clusters, and transportation networks (highways, freight corridors).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.environment.ecosystems_ecology', 'General Studies', 'environment', 'Ecosystem Dynamics, Biomes & Ecological Principles', 'Trophic levels, food chains and webs, ecological pyramids, ecological succession, and biogeochemical nutrient cycles.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.environment.biodiversity_conservation', 'General Studies', 'environment', 'Biodiversity Hotspots, In-Situ/Ex-Situ Conservation & Wildlife', 'Biodiversity hotspots in India, IUCN Red List, National Parks, Sanctuaries, Biosphere Reserves, and Project Tiger/Elephant.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.environment.climate_change_treaties', 'General Studies', 'environment', 'Global Climate Change, Greenhouse Effect & International Treaties', 'UNFCCC, Paris Agreement (NDCs), global warming, greenhouse gases, IPCC assessments, and Montreal Protocol.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.environment.pollution_legislation', 'General Studies', 'environment', 'Environmental Pollution, Solid Waste & Regulatory Framework', 'Air Quality Index (AQI), water pollution, plastic waste rules, Wildlife Protection Act 1972, EPA 1986, and NGT.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.science_tech.everyday_science', 'General Studies', 'science_tech', 'General Science, Human Biology, Nutrition & Public Health', 'Human physiology, genetics, communicable and lifestyle diseases, immunology, vaccines, antibiotics, and nutrition.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.science_tech.space_astronomy', 'General Studies', 'science_tech', 'Space Technology, ISRO Missions & Satellite Architecture', 'ISRO launch vehicles (PSLV, LVM3), satellite orbits, NavIC GPS, Chandrayaan, Gaganyaan, and Aditya-L1 missions.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.science_tech.defense_nuclear', 'General Studies', 'science_tech', 'Defense Technologies, Missiles & Nuclear Energy Program', 'DRDO missile systems (Agni, BrahMos), aircraft carriers, submarines, and India''s three-stage nuclear power program.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.science_tech.emerging_technologies', 'General Studies', 'science_tech', 'Emerging & Frontier Technologies', 'Artificial Intelligence, Quantum Computing, Blockchain, CRISPR gene editing, 5G/6G telecom, and nanotechnology.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.economy_gen.planning_niti_growth', 'General Studies', 'economy_gen', 'Economic Planning, Growth Models & NITI Aayog Strategy', 'Transition from Planning Commission to NITI Aayog, sustainable development goals (SDGs), and inclusive economic growth.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.economy_gen.poverty_inequality_employment', 'General Studies', 'economy_gen', 'Poverty Alleviation, Inequality & Employment Generation', 'Poverty measurement methodologies, Multidimensional Poverty Index (MPI), Gini coefficient, PLFS data, and MGNREGA.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.economy_gen.agriculture_rural_economy', 'General Studies', 'economy_gen', 'Agricultural Economics, Food Security & Rural Development', 'MSP, CACP pricing, PM-KISAN, crop insurance schemes, National Food Security Act (NFSA 2013), and PDS reforms.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.economy_gen.infrastructure_industrial', 'General Studies', 'economy_gen', 'Infrastructure, Industrial Policy & Manufacturing Growth', 'PM Gati Shakti, National Infrastructure Pipeline, Make in India, PLI schemes, SEZs, and industrial corridors.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ir_security.foreign_policy_neighborhood', 'General Studies', 'ir_security', 'India''s Foreign Policy, Bilateral Alliances & Neighborhood', 'Neighborhood First, Act East policy, SAGAR doctrine, Indo-Pacific diplomacy, and strategic bilateral partnerships.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ir_security.multilateral_orgs', 'General Studies', 'ir_security', 'Global Governance, Multilateral Institutions & Regional Blocs', 'UNSC reforms, WTO dispute settlement, IMF, World Bank, G20 Presidency priorities, BRICS, SCO, and Quad alliance.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ir_security.internal_security_threats', 'General Studies', 'ir_security', 'Internal Security Challenges, Border Management & Extremism', 'Cross-border terrorism, Left-Wing Extremism (LWE), border management, CAPF roles, NIA, and UAPA statutory provisions.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ir_security.cyber_financial_crimes', 'General Studies', 'ir_security', 'Cyber Security, Critical Information Infrastructure & Financial Crimes', 'Cyber warfare, CERT-In guidelines, critical information infrastructure protection, PMLA 2002, and FATF regulations.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ethics.ethical_frameworks', 'General Studies', 'ethics', 'Ethics, Human Values & Moral Philosophy', 'Determinants and consequences of ethics, moral philosophers (Indian and Western), deontological and utilitarian ethics.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ethics.attitude_emotional_intel', 'General Studies', 'ethics', 'Attitude, Moral Aptitude & Emotional Intelligence in Governance', 'Moral and political attitudes, social influence, persuasion, and emotional intelligence in civil administration.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ethics.public_probity_governance', 'General Studies', 'ethics', 'Probity in Governance, Transparency & Anti-Corruption Mechanisms', 'Probity in public service, Right to Information (RTI Act 2005), Citizen''s Charters, codes of conduct, and Lokpal.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.ethics.administrative_case_studies', 'General Studies', 'ethics', 'Administrative Case Studies & Dilemma Resolution', 'Practical administrative ethical dilemmas, public interest vs executive pressure, conflict of interest, and case analysis.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.state_gk.history_culture_regional', 'General Studies', 'state_gk', 'State-Specific History, Heritage & Cultural Movements', 'State history, regional dynasties, freedom struggle contributions, regional art, literature, and local folk festivals.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.state_gk.geography_environment_regional', 'General Studies', 'state_gk', 'State Physiography, River Basins & Environmental Profiling', 'State physical divisions, river basins, regional mineral reserves, state wildlife sanctuaries, and climatic features.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.state_gk.polity_governance_regional', 'General Studies', 'state_gk', 'State Administrative Structure, Judiciary & Local Governance', 'State Vidhan Sabha/Parishad, Governor''s role, State High Court, State Public Service Commission, and Panchayati Raj.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('gs.state_gk.economy_development_regional', 'General Studies', 'state_gk', 'State Economic Profile, Sectoral Allocations & Flagship Schemes', 'State Gross Domestic Product (SGDP), state budget, fiscal deficits, regional industrial hubs, and state welfare schemes.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.arithmetic.percentages_profit_loss', 'Quantitative Aptitude', 'arithmetic', 'Percentages, Profit, Loss, Mark-up & Discounts', 'Successive percentage changes, profit and loss margins, marked price, discounts, and dishonest dealer problems.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.arithmetic.simple_compound_interest', 'Quantitative Aptitude', 'arithmetic', 'Simple & Compound Interest, Compounding Periods & Installments', 'Simple interest, compound interest (annual/half-yearly), difference between CI and SI, and equated loan installments.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.arithmetic.ratio_proportion_variation', 'Quantitative Aptitude', 'arithmetic', 'Ratio, Proportion & Direct/Inverse Variation', 'Compounded ratios, mean and third/fourth proportionals, direct and inverse variations, and proportional division.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.arithmetic.mixtures_alligations', 'Quantitative Aptitude', 'arithmetic', 'Mixtures, Alligation Rules & Repeated Replacement', 'Rule of alligation, combining solutions of different concentrations, and repeated replacement of liquids from vessels.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.arithmetic.partnership_shares', 'Quantitative Aptitude', 'arithmetic', 'Business Partnerships, Capital-Duration Ratio & Profit Distribution', 'Partnership investments, capital-time ratio, working versus sleeping partners, and profit-sharing computations.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.averages_ages.average_concepts', 'Quantitative Aptitude', 'averages_ages', 'Averages, Weighted Averages & Inclusions/Exclusions', 'Arithmetic mean, weighted average formula, change in average on inclusion or replacement of members, and batting averages.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.averages_ages.problems_on_ages', 'Quantitative Aptitude', 'averages_ages', 'Linear Age Relations & Time-Shift Projections', 'Formulation and solution of linear equations based on past, present, and future chronological age ratios.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.time_work.work_efficiency_wages', 'Quantitative Aptitude', 'time_work', 'Time, Work, Worker Efficiency & Wage Distribution', 'Unitary work method, individual and combined worker efficiencies, alternate day working, and proportional wages.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.time_work.pipes_cisterns', 'Quantitative Aptitude', 'time_work', 'Pipes, Cisterns, Inflow/Outflow Rates & Leakages', 'Inlet and outlet pipe flow rates, tank emptying times via leakages, and alternating pipe filling problems.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.time_distance.speed_time_relative', 'Quantitative Aptitude', 'time_distance', 'Speed, Time, Distance Basics & Relative Velocity', 'Average speed calculations, unit conversions (km/h to m/s), and relative velocity in same and opposite directions.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.time_distance.trains_platforms', 'Quantitative Aptitude', 'time_distance', 'Problems on Trains, Platforms, Bridges & Tunnels', 'Trains crossing stationary poles/persons, platforms, bridges, and trains moving on parallel tracks.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.time_distance.boats_streams_races', 'Quantitative Aptitude', 'time_distance', 'Boats, Streams, River Currents & Linear/Circular Races', 'Upstream and downstream river velocities, still water boat speeds, headstarts, and circular track lap meetings.');
