INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.algebra.linear_equations', 'Quantitative Aptitude', 'algebra', 'Linear Equations in One, Two & Three Variables', 'Simultaneous equations, consistency and inconsistency of systems, and algebraic formulation of word problems.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.algebra.quadratic_equations', 'Quantitative Aptitude', 'algebra', 'Quadratic Equations, Nature of Roots & Optimization', 'Standard quadratic form, discriminant, nature of roots, Vieta''s relations, and quadratic graph optimization.');
