INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.trigonometry.heights_distances', 'Quantitative Aptitude', 'trigonometry', 'Heights and Distances & Angular Observations', 'Angle of elevation, angle of depression, line of sight, and distance/height problems involving towers and ships.');
