INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.di_ds.tables_bar_line_charts', 'Quantitative Aptitude', 'di_ds', 'Data Interpretation: Tables, Bar Charts & Line Graphs', 'Tabular data extraction, single and stacked bar charts, histograms, and time-series line graphs.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.di_ds.pie_radar_mixed_charts', 'Quantitative Aptitude', 'di_ds', 'Data Interpretation: Pie Charts, Radar Plots & Mixed Graphs', 'Single/double pie charts, degree to percentage conversions, radar charts, and mixed composite graph sets.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.di_ds.caselet_di', 'Quantitative Aptitude', 'di_ds', 'Data Interpretation: Caselets & Paragraph-Based Sets', 'Unstructured paragraph caselets, Venn diagram caselets, and multi-variable arithmetic narrative interpretation.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('quant.di_ds.data_sufficiency', 'Quantitative Aptitude', 'di_ds', 'Data Sufficiency in Quantitative Problem Solving', 'Two-statement and three-statement data sufficiency evaluation across arithmetic, algebra, and geometry problems.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.puzzles_seating.linear_circular_seating', 'Reasoning', 'puzzles_seating', 'Linear & Circular/Polygonal Seating Arrangements', 'Single/double row seating facing North/South, and circular/polygonal table seating facing inward and outward.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.puzzles_seating.floor_box_puzzles', 'Reasoning', 'puzzles_seating', 'Floor, Flat & Box Stacking Arrangement Puzzles', 'Multi-floor building puzzles (floors 1 to 10), flat-floor combinations, and vertical box stacking order.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.puzzles_seating.scheduling_matrix', 'Reasoning', 'puzzles_seating', 'Day, Month, Year Scheduling & Multi-Attribute Matrix Puzzles', 'Scheduling across days of the week, months and dates, and multi-attribute matrix matching grids.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.coding_decoding.letter_symbol_coding', 'Reasoning', 'coding_decoding', 'Letter Shifting, Substitution & Symbol Coding', 'Letter shifts, reverse alphabet, symbol coding, conditional matrix coding, and fictitious language ciphering.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.coding_decoding.number_alphabet_series', 'Reasoning', 'coding_decoding', 'Number Series, Alphanumeric Sequences & Pattern Completion', 'Arithmetic and geometric difference series, alphanumeric sequences, and wrong term identification.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.blood_relations.family_tree_logic', 'Reasoning', 'blood_relations', 'Family Tree Construction & Direct Relational Puzzles', 'Narrative family tree construction, generation linking, and ''pointing to a person'' relationship problems.');
