INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.direction_distance.shadow_clock_angles', 'Reasoning', 'direction_distance', 'Shadow Direction Dynamics & Clock Hand Orientations', 'Sun-shadow dynamics at sunrise and sunset, facing directions, and directional clock hand orientation.');
