INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.verbal_logic.syllogisms_possibility', 'Reasoning', 'verbal_logic', 'Modern Syllogisms: ''Only a Few'', Possibility Cases & Reverse Syllogisms', 'Advanced syllogisms featuring ''Only a few'', possibility conclusions, ''can never be'', and reverse syllogisms.');
