INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.critical_reasoning.statement_assumptions', 'Reasoning', 'critical_reasoning', 'Statement and Assumptions: Unstated Premises & Validity', 'Identifying implicit, unstated premises upon which a stated argument or policy relies.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.critical_reasoning.statement_arguments', 'Reasoning', 'critical_reasoning', 'Statement and Arguments: Strong vs. Weak Arguments', 'Evaluating arguments on controversial policies; differentiating strong fact-based arguments from weak biased ones.');
