INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.order_ranking.linear_ranking', 'Reasoning', 'order_ranking', 'Linear Order & Ranking in a Row', 'Calculating total count from left/right rankings, intermediate entity counts, and interchanged seat positions.');
