INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.input_output.mathematical_box_operations', 'Reasoning', 'input_output', 'Advanced Machine Input-Output: Mathematical Block Operations', 'Multi-step machine input models operating on two-digit numerical blocks via mathematical transformations.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.non_verbal.series_analogy_classification', 'Reasoning', 'non_verbal', 'Figure Series, Analogy & Odd-One-Out Classification', 'Identifying rotational symmetry, element movement within frames, figure analogies, and odd-one-out figures.');
