INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.non_verbal.paper_folding_cutting', 'Reasoning', 'non_verbal', 'Paper Folding, Paper Cutting & Pattern Punching', 'Sequential folding of transparent paper, punching geometric cuts, and reconstructing the unfolded pattern.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('reasoning.non_verbal.cube_dice_embedded', 'Reasoning', 'non_verbal', 'Cubes, Dice Opposites & Embedded Figures', 'Opposite face determination from multiple dice views, unfolding cube net layouts, and finding embedded figures.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.reading_comprehension.factual_main_idea', 'English', 'reading_comprehension', 'Reading Comprehension: Central Idea, Primary Purpose & Factual Recall', 'Central thesis identification, primary purpose, appropriate title formulation, and explicit factual retrieval.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.reading_comprehension.inference_author_tone', 'English', 'reading_comprehension', 'Reading Comprehension: Implicit Inferences, Mood & Author''s Tone', 'Implicit meanings, contextual nuance, determining author''s attitude/tone (satirical, analytical, objective), and subtext.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.reading_comprehension.structural_argument', 'English', 'reading_comprehension', 'Reading Comprehension: Passage Structure, Logical Flow & Counter-Theses', 'Paragraph transitions, premise-conclusion arguments, underlying assumptions, and strengthening/weakening propositions.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.grammar_syntax.subject_verb_agreement', 'English', 'grammar_syntax', 'Subject-Verb Agreement (Concord) & Pronoun Reference', 'Grammatical concord rules, collective noun agreements, compound subjects, and pronoun-antecedent agreement.');
