INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.vocabulary_usage.synonyms_antonyms', 'English', 'vocabulary_usage', 'Contextual Synonyms, Antonyms & Semantic Nuances', 'Contextual synonyms and antonyms, nuanced connotations, and distinguishing formal from colloquial lexicon.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.vocabulary_usage.idioms_phrases', 'English', 'vocabulary_usage', 'Idiomatic Expressions, Proverbial Meanings & Figurative Usage', 'Classical English idioms, administrative turns of phrase, proverbs, and figurative language usage.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.vocabulary_usage.one_word_substitution', 'English', 'vocabulary_usage', 'One-Word Substitutions & Specialized Terminology', 'Concise lexical replacements for verbose phrases, legal terms, scientific classifications, and administrative titles.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.vocabulary_usage.spelling_confusing_words', 'English', 'vocabulary_usage', 'Spelling Accuracy, Homophones, Homonyms & Paronyms', 'Correct spelling of complex words, commonly confused word pairs (affect/effect), and homophonic clarity.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.verbal_ability.para_jumbles_sentence_rearrangement', 'English', 'verbal_ability', 'Para Jumbles & Sentence Rearrangement for Coherence', 'Paragraph coherence from jumbled sentence fragments, identifying opening/topic sentences and transition markers.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.verbal_ability.cloze_test_fillers', 'English', 'verbal_ability', 'Cloze Tests, Single/Double Sentence Fillers & Fill-in-the-Blanks', 'Thematic passage completion (cloze test) and single/double sentence fillers requiring grammatical agreement.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.verbal_ability.sentence_improvement_connectors', 'English', 'verbal_ability', 'Sentence Improvement, Sentence Starters & Discourse Connectors', 'Sentence correction, sentence starters, and joining clauses using logical discourse connectors.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.descriptive_writing.essay_composition', 'English', 'descriptive_writing', 'Descriptive Essay Formulation & Argumentative Composition', 'Structured descriptive, analytical, and argumentative essays on socio-economic, governance, and policy topics.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.descriptive_writing.precis_writing', 'English', 'descriptive_writing', 'Precis Writing: Summarization & Salient Point Retention', 'Condensing extended passages into precisely one-third length, retaining core arguments and avoiding verbatim copying.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.descriptive_writing.formal_letter_memo', 'English', 'descriptive_writing', 'Official Correspondence: Formal Letters, Memoranda & Representations', 'Official government letters, representations, business correspondence, and internal office memoranda protocol.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('english.descriptive_writing.report_counter_argument', 'English', 'descriptive_writing', 'Analytical Report Writing & Pro/Con Argument Drafting', 'Formal administrative event reports and writing balanced arguments for and against controversial propositions.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.macroeconomics.national_income_aggregates', 'Economics & Finance', 'macroeconomics', 'National Income Aggregates, GVA & Output Accounting', 'GDP, GNP, NNP, National Income at Factor Cost versus Market Prices, Gross Value Added (GVA), and GDP Deflator.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.macroeconomics.inflation_price_indices', 'Economics & Finance', 'macroeconomics', 'Inflation Dynamics, Price Indices & Phillips Curve', 'Demand-pull and cost-push inflation, CPI-Combined, WPI, Core vs Headline inflation, and Phillips curve trade-offs.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.macroeconomics.consumption_investment_models', 'Economics & Finance', 'macroeconomics', 'Keynesian Aggregate Demand, Investment Multiplier & IS-LM Model', 'Keynesian consumption function, marginal propensity to consume/save, investment multiplier, and IS-LM framework.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.macroeconomics.business_cycles_growth', 'Economics & Finance', 'macroeconomics', 'Business Cycles, Potential Output & Economic Growth Theories', 'Phases of business cycles, output gap, potential GDP, and exogenous/endogenous growth models (Solow, Harrod-Domar).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.monetary_policy.rbi_framework_instruments', 'Economics & Finance', 'monetary_policy', 'RBI Monetary Policy Framework, MPC & Inflation Targeting', 'RBI Act 1934 provisions, Monetary Policy Committee (MPC) voting, and statutory Flexible Inflation Targeting (4±2%).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.monetary_policy.liquidity_operations', 'Economics & Finance', 'monetary_policy', 'Liquidity Management Instruments: Repo, SDF, MSF & Reserve Ratios', 'Policy Repo Rate, Standing Deposit Facility (SDF), Marginal Standing Facility (MSF), CRR, SLR, and OMO operations.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.monetary_policy.money_supply_aggregates', 'Economics & Finance', 'monetary_policy', 'Monetary Aggregates, High-Powered Money & Money Multiplier', 'Reserve money (M0), narrow money (M1), broad money (M3), currency-deposit ratio, and money multiplier mechanics.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.fiscal_policy.union_budget_deficits', 'Economics & Finance', 'fiscal_policy', 'Union Budget Concepts, Deficit Metrics & FRBM Act', 'Revenue and Capital accounts, Revenue/Fiscal/Primary Deficits, and FRBM Act 2003 fiscal targets.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.fiscal_policy.taxation_direct_indirect', 'Economics & Finance', 'fiscal_policy', 'Tax Policy, Direct Taxes & GST Framework', 'Canons of taxation, Corporate income tax, Goods and Services Tax (GST) architecture, GST Council, and Input Tax Credit.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.fiscal_policy.public_debt_finance_commission', 'Economics & Finance', 'fiscal_policy', 'Public Debt Management & Finance Commission Transfers', 'Internal and external public debt, debt-to-GDP ratios, Finance Commission horizontal/vertical devolution criteria.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.financial_markets.money_market_instruments', 'Economics & Finance', 'financial_markets', 'Money Market Architecture & Short-Term Instruments', 'Call money, Treasury Bills (91, 182, 364 days), Commercial Paper (CP), Certificates of Deposit (CD), and TREPS.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.financial_markets.capital_markets_equity_debt', 'Economics & Finance', 'financial_markets', 'Capital Markets: Primary Equity Issues & Bond Valuations', 'Primary market offerings (IPO, FPO, Rights Issue), secondary trading, G-Secs, bond valuation, YTM, and duration.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.financial_markets.derivatives_risk_management', 'Economics & Finance', 'financial_markets', 'Financial Derivatives, Option Pricing & Hedging Strategies', 'Forwards, Futures, European/American Call and Put options, interest rate swaps, hedging, and Black-Scholes model.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.financial_markets.sebi_regulatory_framework', 'Economics & Finance', 'financial_markets', 'SEBI Governance, Securities Laws & Market Infrastructure', 'SEBI Act 1992, ICDR Regulations, LODR Regulations, Prohibition of Insider Trading (PIT), and Depositories Act.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.banking_systems.structure_commercial_banks', 'Economics & Finance', 'banking_systems', 'Structure & Evolution of the Indian Banking System', 'Scheduled commercial banks, Small Finance Banks, Payments Banks, Regional Rural Banks, and Banking Regulation Act 1949.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.banking_systems.basel_capital_framework', 'Economics & Finance', 'banking_systems', 'Basel Capital Accords, CRAR & Prudential Norms', 'Basel III standards, Capital Adequacy Ratio (CRAR), Tier 1/2 capital, Leverage Ratio, LCR, and NSFR ratios.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.banking_systems.npa_resolution_ibc', 'Economics & Finance', 'banking_systems', 'Non-Performing Assets (NPAs), Provisioning & IBC 2016', 'Asset classification (SMA-0/1/2, Substandard, Doubtful, Loss), SARFAESI Act, IBC 2016, and Bad Bank (NARCL-IDRCL).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.banking_systems.priority_sector_financial_inclusion', 'Economics & Finance', 'banking_systems', 'Priority Sector Lending (PSL) & Financial Inclusion Architecture', 'RBI Priority Sector Lending (PSL) mandates, PM Jan Dhan Yojana, PM Mudra Yojana, and Financial Inclusion Index.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.regulatory_bodies.pension_architecture_pfrda', 'Economics & Finance', 'regulatory_bodies', 'Pension Regulatory Framework, PFRDA & National Pension System (NPS)', 'PFRDA Act 2013, National Pension System (NPS) architecture, Tier I/II accounts, and Atal Pension Yojana (APY).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.regulatory_bodies.ifsca_gift_city', 'Economics & Finance', 'regulatory_bodies', 'International Financial Services Centres Authority (IFSCA) & GIFT City', 'IFSCA Act 2019, GIFT City ecosystem, offshore banking units, bullion exchange, and aircraft/ship leasing rules.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.regulatory_bodies.nabard_rural_credit', 'Economics & Finance', 'regulatory_bodies', 'NABARD Mandate, Rural Infrastructure Development Fund (RIDF) & Agri-Credit', 'NABARD Act 1981, Rural Infrastructure Development Fund (RIDF), agri-credit refinancing, and cooperative banking supervision.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.regulatory_bodies.sidbi_msme_ecosystem', 'Economics & Finance', 'regulatory_bodies', 'SIDBI Mandate, MSME Credit Architecture & Trade Receivables (TReDS)', 'SIDBI, MSMED Act 2006 classification criteria, CGTMSE credit guarantee funds, and TReDS factoring platform.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.corporate_finance.financial_statement_analysis', 'Economics & Finance', 'corporate_finance', 'Corporate Financial Statements: Balance Sheet, P&L & Cash Flow', 'Balance Sheet, Statement of Profit and Loss, and Cash Flow Statement analysis across operating, investing, and financing.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.corporate_finance.ratio_analysis_liquidity_solvency', 'Economics & Finance', 'corporate_finance', 'Financial Ratio Analysis: Liquidity, Solvency, Activity & Profitability', 'Current/Quick ratios, Debt-to-Equity, Interest Coverage, Return on Equity (ROE), ROCE, and DuPont analysis.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.corporate_finance.capital_budgeting_cost_of_capital', 'Economics & Finance', 'corporate_finance', 'Capital Budgeting Evaluation & Weighted Average Cost of Capital (WACC)', 'Capital budgeting (NPV, IRR, Payback Period), Cost of Equity (CAPM), and Weighted Average Cost of Capital (WACC).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.accounting_costing.accounting_standards_indas', 'Economics & Finance', 'accounting_costing', 'Accounting Principles, Indian Accounting Standards (Ind AS) & Auditing', 'Fundamental accounting assumptions, Ind AS aligned with IFRS, revenue recognition rules, and statutory auditing.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.accounting_costing.cost_accounting_marginal', 'Economics & Finance', 'accounting_costing', 'Cost Accounting, Marginal Costing & Break-Even Analysis', 'Elements of cost, Marginal Costing, Cost-Volume-Profit (CVP) analysis, Contribution margin, and Break-Even Point (BEP).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.management_org.management_principles_theories', 'Economics & Finance', 'management_org', 'Foundational Management Thought & Organizational Principles', 'Scientific Management (Taylor), 14 Principles of Management (Fayol), Bureaucracy (Weber), and Hawthorne studies (Mayo).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.management_org.organizational_behavior_leadership', 'Economics & Finance', 'management_org', 'Organizational Behavior, Motivation Models & Leadership Styles', 'Motivation models (Maslow, Herzberg, Vroom), leadership styles (transformational, transactional), and group dynamics.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('econ_fin.management_org.corporate_governance_ethics', 'Economics & Finance', 'management_org', 'Corporate Governance Principles, Board Mandates & CSR', 'Codes of corporate governance, role of Independent Directors, Board audit committees, and Section 135 CSR mandates.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.computer_science.data_structures', 'Technical', 'computer_science', 'Data Structures: Arrays, Linked Lists, Trees, Heaps & Graphs', 'Arrays, linked lists, stacks, queues, binary search trees (BST), AVL trees, binary heaps, hash tables, and graphs.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.computer_science.algorithms_complexity', 'Technical', 'computer_science', 'Algorithms & Asymptotic Complexity Analysis', 'Asymptotic notations (Big O), Master Theorem, Quicksort, Mergesort, Dynamic Programming, Dijkstra, and NP-completeness.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.computer_science.operating_systems', 'Technical', 'computer_science', 'Operating Systems: Process Scheduling, Concurrency & Virtual Memory', 'Process scheduling, threads, semaphores, mutexes, deadlock avoidance (Banker''s algorithm), and virtual memory.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.computer_science.database_management', 'Technical', 'computer_science', 'Database Management Systems (DBMS), Relational Algebra & SQL', 'Relational data model, relational algebra, SQL DDL/DML, normalization up to BCNF, indexing, and ACID transactions.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.computer_science.computer_networks', 'Technical', 'computer_science', 'Computer Networks: OSI/TCP-IP Protocols, Routing & Security', 'OSI and TCP/IP protocol architectures, IPv4/IPv6 subnetting, routing protocols (OSPF, BGP), and TCP flow control.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.computer_science.software_eng_cloud', 'Technical', 'computer_science', 'Software Engineering, Cloud Computing & System Design', 'SDLC, Agile Scrum methodologies, design patterns, microservices architecture, REST APIs, and cloud computing (IaaS/PaaS).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electronics_comm.semiconductor_devices', 'Technical', 'electronics_comm', 'Semiconductor Physics, Diodes, Transistors & Op-Amps', 'PN junction diodes, Zener diodes, BJT characteristics, MOSFET operational physics, and Op-Amp circuits.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electronics_comm.digital_circuits', 'Technical', 'electronics_comm', 'Digital Electronic Circuits, Logic Gates & Sequential Systems', 'Boolean algebra, Karnaugh maps (K-maps), combinational logic (adders, multiplexers), and sequential flip-flops.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electronics_comm.signals_systems', 'Technical', 'electronics_comm', 'Signals and Systems: Fourier, Laplace & Z-Transforms', 'Continuous/discrete-time signals, LTI systems, convolution, Fourier Transform, Laplace Transform, and Z-Transform.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electronics_comm.analog_digital_comm', 'Technical', 'electronics_comm', 'Analog & Digital Communication Systems', 'AM, FM, sampling theorem, Pulse Code Modulation (PCM), digital modulation (ASK, FSK, PSK, QAM), and channel capacity.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electrical_eng.electric_circuits_fields', 'Technical', 'electrical_eng', 'Electric Circuits, Network Theorems & Transient Analysis', 'Kirchhoff''s laws, Thevenin and Norton theorems, transient response of RL/RC/RLC circuits, and three-phase circuits.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electrical_eng.electrical_machines', 'Technical', 'electrical_eng', 'Electrical Machines: Transformers, Induction & Synchronous Machines', 'Single/three-phase transformers, DC machines, three-phase induction motor torque-slip curves, and synchronous generators.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electrical_eng.power_systems_grid', 'Technical', 'electrical_eng', 'Power System Transmission, Fault Analysis & Grid Protection', 'Overhead transmission lines, per-unit system, symmetrical/unsymmetrical fault analysis, and power flow studies.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electrical_eng.control_systems', 'Technical', 'electrical_eng', 'Control Systems Engineering: Transfer Functions & Stability Analysis', 'Transfer function derivation, block diagrams, signal flow graphs, Routh-Hurwitz stability, Root Locus, and Bode plots.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.electrical_eng.power_electronics', 'Technical', 'electrical_eng', 'Power Electronics: Converters, Inverters & Motor Drives', 'SCR, MOSFET, IGBT characteristics, phase-controlled rectifiers, DC-DC buck/boost converters, and PWM inverters.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.mechanical_eng.thermodynamics_cycles', 'Technical', 'mechanical_eng', 'Thermodynamics, Thermodynamic Cycles & Power Plant Engineering', 'Laws of thermodynamics, entropy, ideal gas power cycles (Carnot, Otto, Diesel, Brayton), and Rankine steam cycle.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.mechanical_eng.fluid_mechanics_turbo', 'Technical', 'mechanical_eng', 'Fluid Mechanics, Boundary Layer Theory & Turbo-Machinery', 'Fluid statics, Navier-Stokes equations, Bernoulli''s theorem, boundary layer theory, hydraulic turbines, and pumps.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.mechanical_eng.heat_transfer', 'Technical', 'mechanical_eng', 'Heat Transfer: Conduction, Convection, Radiation & Heat Exchangers', 'Fourier''s law, free/forced convection (dimensionless numbers), thermal radiation (Stefan-Boltzmann), and heat exchangers.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.mechanical_eng.engineering_mechanics_som', 'Technical', 'mechanical_eng', 'Engineering Mechanics & Strength of Materials (SOM)', 'Free body diagrams, trusses, Mohr''s circle of stress, shear force and bending moment diagrams, and torsion of shafts.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.mechanical_eng.theory_of_machines', 'Technical', 'mechanical_eng', 'Theory of Machines, Mechanisms & Mechanical Vibrations', 'Kinematic inversions, gear trains, flywheels, governors, balancing of rotating masses, and single-DOF vibrations.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.mechanical_eng.manufacturing_materials', 'Technical', 'mechanical_eng', 'Manufacturing Engineering, Material Science & Metrology', 'Metal casting, forming, welding, metal cutting (Merchant circle), Iron-Carbon phase equilibrium diagram, and metrology.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.civil_eng.structural_analysis', 'Technical', 'civil_eng', 'Structural Analysis: Determinate & Indeterminate Structures', 'Trusses, beams, frames analysis, moment distribution method, slope-deflection, and stiffness matrix methods.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.civil_eng.design_concrete_steel', 'Technical', 'civil_eng', 'Design of Reinforced Concrete (RCC) & Steel Structures', 'Limit State RCC design (IS 456) for beams/slabs/columns, prestressed concrete, and design of steel connections (IS 800).');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.civil_eng.geotechnical_soil_mechanics', 'Technical', 'civil_eng', 'Geotechnical Engineering, Soil Mechanics & Foundation Design', 'Soil classification, permeability, consolidation theory, Mohr-Coulomb shear strength, and foundation bearing capacity.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.civil_eng.water_resources_environmental', 'Technical', 'civil_eng', 'Water Resources, Irrigation Engineering & Environmental Engineering', 'Hydrological cycle, unit hydrograph, irrigation water requirements, water treatment processes, and wastewater BOD/COD.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.civil_eng.transportation_surveying', 'Technical', 'civil_eng', 'Transportation Engineering, Pavement Design & Modern Surveying', 'Highway geometric design, sight distances, pavement design, theodolite surveying, levelling, and GPS/GIS fundamentals.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.geology_geophysics.physical_structural_geology', 'Technical', 'geology_geophysics', 'Physical Geology, Geodynamics & Structural Geology', 'Earth interior, plate tectonics, rock deformation mechanics, folds, faults, joints, unconformities, and geological mapping.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.geology_geophysics.mineralogy_petrology', 'Technical', 'geology_geophysics', 'Crystallography, Optical Mineralogy & Petrology', 'Crystal symmetry classes, optical properties of minerals, petrology of igneous/sedimentary/metamorphic rocks.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.geology_geophysics.economic_hydrogeology', 'Technical', 'geology_geophysics', 'Economic Geology, Mineral Deposits of India & Hydrogeology', 'Ore forming processes, mineral deposits of India, groundwater hydrology, aquifer types, and well hydraulics.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.geology_geophysics.applied_geophysics', 'Technical', 'geology_geophysics', 'Applied Exploration Geophysics: Seismic, Gravity, Magnetic & Electrical', 'Seismic reflection/refraction, gravity and magnetic prospecting, electrical resistivity surveys, and well logging.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.statistics_econometrics.probability_distributions', 'Technical', 'statistics_econometrics', 'Probability Distributions, Random Variables & Limit Theorems', 'Random variables, Binomial, Poisson, Normal, Exponential distributions, Central Limit Theorem, and Chebyshev inequality.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.statistics_econometrics.statistical_inference_tests', 'Technical', 'statistics_econometrics', 'Statistical Inference, Estimation & Hypothesis Testing', 'Point and interval estimation, Maximum Likelihood, hypothesis testing (z, t, F, Chi-Square tests), and ANOVA.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.statistics_econometrics.sampling_design', 'Technical', 'statistics_econometrics', 'Survey Sampling Theory & Experimental Designs', 'Simple random sampling, stratified sampling, cluster sampling, systematic sampling, and randomized block designs.');
INSERT OR REPLACE INTO syllabus_taxonomy (topic_id, domain, sub_domain, topic_title, description) VALUES ('tech.statistics_econometrics.regression_econometric_models', 'Technical', 'statistics_econometrics', 'Econometrics, Multiple Regression & Time Series Forecasting', 'Classical linear regression (OLS), Gauss-Markov theorem, multicollinearity, heteroscedasticity, and ARIMA models.');

